function renderRoutine(){$('#routineList').innerHTML=routine.map(r=>`<div class="routine-item"><time>${r[0]}</time><span class="routine-dot">${r[1]}</span><div><strong>${r[2]}</strong><small>${r[3]}</small></div></div>`).join('')}
function renderRules(){$('#ruleCount').textContent=`${rules.length} rules`;$('#rulesList').innerHTML=rules.map((r,i)=>`<div class="rule-item"><span class="rule-number">0${i+1}</span><p>${escapeHtml(r)}</p><button data-del-rule="${i}">×</button></div>`).join('');$$('[data-del-rule]').forEach(b=>b.onclick=()=>{rules.splice(+b.dataset.delRule,1);store.set('tide_rules',rules);renderRules()})}
function spokenNumber(text){let words={one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10,half:.5};let m=text.match(/\d+(?:\.\d+)?/);if(m)return+m[0];for(let w in words)if(new RegExp('\\b'+w+'\\b').test(text))return words[w];return 1}
function durationMinutes(text){let n=spokenNumber(text);if(/hour|hr\b/.test(text))return n*60;if(/minute|min\b/.test(text))return n;return 60}
function analyseRoutineText(raw){let text=raw.toLowerCase(),n=spokenNumber(text),now=new Date().toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'}),base={id:'routine-'+Date.now().toString(36),text:raw,time:now};
 const foods={burger:520,'pizza':285,'roti':110,'chapati':110,'egg':78,'banana':105,'apple':95,'rice':205,'chicken':240,'sandwich':350,'coffee':80,'tea':60,'salad':150,'dal':180,'biryani':550};let food=Object.keys(foods).find(x=>text.includes(x));
 if(food){let kcal=Math.round(foods[food]*n);return{...base,category:'Food',icon:'♨',value:kcal,unit:'kcal',detail:`Estimated ${n} × ${food} · editable`}}
 if(/water|hydration|litre|liter|\bml\b/.test(text)){let amount=n;if(/litre|liter|\bl\b/.test(text))amount*=1000;if(!/ml|litre|liter|\bl\b/.test(text))amount*=250;return{...base,category:'Water',icon:'≈',value:Math.round(amount),unit:'ml',detail:'Added to hydration'}}
 if(/workout|gym|run|running|walk|cycling|exercise|yoga|swim/.test(text)){let min=durationMinutes(text),rate=/run|running/.test(text)?600:/walk/.test(text)?250:/cycling/.test(text)?500:/yoga/.test(text)?220:/swim/.test(text)?550:450,burn=Math.round(min/60*rate);return{...base,category:'Workout',icon:'⌁',value:burn,unit:'kcal burned',detail:`${Math.round(min)} min · estimated`}}
 if(/sleep|slept|nap/.test(text)){let hours=durationMinutes(text)/60;return{...base,category:'Sleep',icon:'☾',value:+hours.toFixed(1),unit:'hours',detail:hours>=7?'Good recovery':'Below sleep target'}}
 if(/work|focus|meeting|proposal|office|client/.test(text)){let hours=durationMinutes(text)/60;return{...base,category:'Work',icon:'→',value:+hours.toFixed(1),unit:'hours',detail:'Focused work logged'}}
 return{...base,category:'Personal',icon:'♡',value:1,unit:'entry',detail:'Personal routine note'}
}
function trackRoutineEntry(text){if(!text.trim())return null;let entry=analyseRoutineText(text.trim());routineLogs.unshift(entry);store.set('tide_routine_logs',routineLogs);renderRoutineTracker();toast(`${entry.category} tracked automatically · ${entry.value} ${entry.unit}`);return entry}
function metricTotal(cat){let list=routineLogs.filter(x=>x.category===cat);if(cat==='Sleep')return list[0]?.value||0;return list.reduce((a,x)=>a+(+x.value||0),0)}
function renderRoutineTracker(){
 let data=[['Food','♨',metricTotal('Food'),'kcal','2,000','#e9824f'],['Water','≈',metricTotal('Water'),'ml','2,500','#3d9db0'],['Workout','⌁',metricTotal('Workout'),'kcal','400','#45a577'],['Sleep','☾',metricTotal('Sleep'),'hrs','8','#7468b1'],['Focus work','→',metricTotal('Work'),'hrs','6','#d79b3e']];
 $('#routineMetrics').innerHTML=data.map(d=>{let target=parseFloat(d[4].replace(',','')),pct=Math.min(1,(+d[2]||0)/target);return`<div class="routine-metric" style="--metric-color:${d[5]};--metric-progress:${pct}"><div class="routine-metric-head"><span class="routine-metric-icon">${d[1]}</span><span>${Math.round(pct*100)}%</span></div><strong>${Number(d[2]).toLocaleString('en-IN',{maximumFractionDigits:1})}</strong><small>${d[3]} · target ${d[4]}</small></div>`}).join('');
 $('#routineTimeline').innerHTML=routineLogs.length?routineLogs.map(x=>`<div class="routine-log"><span class="routine-log-icon">${x.icon}</span><div><strong>${escapeHtml(x.text)}</strong><small>${x.category} · ${x.time} · ${escapeHtml(x.detail)}</small></div><div class="routine-log-value"><b>${x.value}</b><span>${x.unit}</span><button data-delete-routine="${x.id}">×</button></div></div>`).join(''):'<div class="empty-agenda"><span>✦</span><strong>Your timeline is ready</strong><p>Speak or type your first update above.</p></div>';
 $$('[data-delete-routine]').forEach(b=>b.onclick=()=>{routineLogs=routineLogs.filter(x=>x.id!==b.dataset.deleteRoutine);store.set('tide_routine_logs',routineLogs);renderRoutineTracker()});renderRoutineSchedule();renderRoutineReport(currentRoutineReport)
}
function renderRoutineSchedule(){$('#routineSchedule').innerHTML=routineSchedule.map((x,i)=>`<div class="schedule-row"><time>${x.time}</time><span>${x.icon}</span><div><strong>${escapeHtml(x.title)}</strong><small>${x.days} · ${x.category}</small></div><button data-delete-schedule="${i}">×</button></div>`).join('');$$('[data-delete-schedule]').forEach(b=>b.onclick=()=>{routineSchedule.splice(+b.dataset.deleteSchedule,1);store.set('tide_routine_schedule',routineSchedule);renderRoutineSchedule()})}
let currentRoutineReport='daily';
function renderRoutineReport(view='daily'){currentRoutineReport=view;let daily=[68,metricTotal('Water')/2500*100,metricTotal('Workout')/400*100,metricTotal('Sleep')/8*100,metricTotal('Work')/6*100],values=view==='daily'?daily:view==='weekly'?[74,78,63,82,71]:[70,73,68,76,75],labels=['Food','Water','Move','Sleep','Work'];$('#routineReportEyebrow').textContent=view.toUpperCase()+' REPORT';$('#routineReportTitle').textContent=view==='daily'?'How your day is balancing.':view==='weekly'?'Your week, with useful patterns.':'Your month, without the noise.';$('#routineChart').innerHTML=values.map((v,i)=>`<div class="chart-bar-wrap"><div class="chart-bar" style="height:${Math.max(8,Math.min(100,v))}%"></div><span>${labels[i]}</span></div>`).join('');let water=metricTotal('Water'),sleep=metricTotal('Sleep');$('#routineInsight').innerHTML=`<span>✦</span><h3>${view==='daily'?'Today’s AI insight':view==='weekly'?'Weekly pattern':'Monthly direction'}</h3><p>${view==='daily'?(water<1500?'Hydration is the clearest opportunity today. ':'Water is looking steady. ')+(sleep<7?'Aim for an earlier wind-down tonight.':'Your sleep is supporting recovery.'):'Your strongest consistency is focused work. Keep improving sleep and regular movement without trying to perfect every day.'}</p><ul><li>Food and exercise values are estimates</li><li>Tap any entry to review later</li><li>Consistency matters more than one score</li></ul>`;$$('[data-routine-report]').forEach(b=>b.classList.toggle('active',b.dataset.routineReport===view))}
function openRoutineScheduleModal(){modal('Add to routine schedule','Build a timetable that fits your real life.',`<div class="form-field"><label>ROUTINE</label><input id="scheduleTitle" placeholder="e.g. Evening walk"></div><div class="form-field"><label>TIME</label><input id="scheduleTime" type="time"></div><div class="form-field"><label>CATEGORY</label><select id="scheduleCategory"><option>Food</option><option>Water</option><option>Workout</option><option>Sleep</option><option>Work</option><option>Personal</option></select></div><div class="form-field"><label>DAYS</label><select id="scheduleDays"><option>Every day</option><option>Mon–Fri</option><option>Mon, Wed, Fri</option><option>Weekends</option></select></div>`,()=>{let title=$('#scheduleTitle').value.trim(),raw=$('#scheduleTime').value,category=$('#scheduleCategory').value;if(!title||!raw)return toast('Add the routine and time first.');let icons={Food:'♨',Water:'≈',Workout:'⌁',Sleep:'☾',Work:'→',Personal:'♡'},time=new Date('2026-01-01T'+raw).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'});routineSchedule.push({title,time,category,icon:icons[category],days:$('#scheduleDays').value});store.set('tide_routine_schedule',routineSchedule);tasks.push({id:'task-'+Date.now().toString(36),title,time,day:'Today',sub:`Routine · ${category}`,type:category==='Work'?'Work':'Personal',category:'Reminder',done:false});store.set('tide_tasks',tasks);renderTasks();renderRoutineSchedule();$('#modal').classList.remove('open');toast('Added to your routine schedule.')})}
