function prettyDateParts(date){let d=new Date(date+'T00:00:00');return{day:d.toLocaleDateString('en-IN',{day:'2-digit'}),rest:d.toLocaleDateString('en-IN',{month:'short',weekday:'short'})}}
function taskCategory(t){if(t.category&&['Meeting','Reminder','Follow-up','Task'].includes(t.category))return t.category;if(meetings.some(m=>m.title.toLowerCase()===t.title.toLowerCase()&&meetingDateISO(m)===taskDateISO(t)))return'Meeting';if(t.type==='BMC'||t.type==='Personal'||/remind|reminder/i.test(t.title+' '+(t.sub||'')))return'Reminder';if(t.type==='Work'&&/call|follow|client|payment|proposal|lead/i.test(t.title+' '+(t.sub||'')))return'Follow-up';return'Task'}
