function followupTasks(){return tasks.filter(t=>taskCategory(t)==='Follow-up')}
function renderFollowupsPage(){let list=followupTasks().sort((a,b)=>taskDateISO(a).localeCompare(taskDateISO(b)));$('#followupsPageList').innerHTML=list.length?list.map(t=>{let d=prettyDateParts(taskDateISO(t));return`<div class="dedicated-card"><div class="dedicated-date"><strong>${d.day}</strong><span>${d.rest}</span></div><div><h3>${escapeHtml(t.title)}</h3><p>${escapeHtml(t.client||t.sub||'Client follow-up')}</p><div class="dedicated-card-meta"><span>${t.done?'Completed':'Follow-up pending'}</span><span>${escapeHtml(t.client||'Client')}</span></div></div><div class="dedicated-time"><strong>${t.time}</strong><span>${taskDateISO(t)}</span><div class="dedicated-actions"><button data-follow-edit="${t.id}">Edit</button><button data-follow-whatsapp="${t.id}">WhatsApp</button></div></div></div>`}).join(''):'<div class="empty-agenda"><span>↗</span><strong>No follow-ups waiting</strong><p>Add a client follow-up when needed.</p></div>';$$('[data-follow-edit]').forEach(b=>b.onclick=()=>openEditTask(b.dataset.followEdit));$$('[data-follow-whatsapp]').forEach(b=>b.onclick=()=>{let t=tasks.find(x=>x.id===b.dataset.followWhatsapp);window.open('https://wa.me/?text='+encodeURIComponent('Hi, following up regarding '+(t?.title||'our discussion')),'_blank')})}
function renderTasksPage(){let list=tasks.filter(t=>taskCategory(t)==='Task').sort((a,b)=>taskDateISO(a).localeCompare(taskDateISO(b)));$('#tasksPageList').innerHTML=list.length?list.map(t=>{let d=prettyDateParts(taskDateISO(t));return`<div class="dedicated-card"><div class="dedicated-date"><strong>${d.day}</strong><span>${d.rest}</span></div><div><h3 style="${t.done?'text-decoration:line-through;opacity:.55':''}">${escapeHtml(t.title)}</h3><p>${escapeHtml(t.sub||t.type)}</p><div class="dedicated-card-meta"><span>Task</span><span>${t.done?'Completed':'Pending'}</span></div></div><div class="dedicated-time"><strong>${t.time}</strong><span>${taskDateISO(t)}</span><div class="dedicated-actions"><button data-general-open="${t.id}">Open task</button></div></div></div>`}).join(''):'<div class="empty-agenda"><span>☷</span><strong>No general tasks</strong><p>Anything not classified as a meeting, reminder or follow-up appears here.</p></div>';$$('[data-general-open]').forEach(b=>{let t=tasks.find(x=>x.id===b.dataset.generalOpen);b.onclick=()=>openTaskQueue(t?taskDateISO(t):localISO())})}
function openAddReminder(){let now=new Date();modal('Add reminder','It will appear here and in your To Do List.',`<div class="form-field"><label>REMINDER</label><input id="newReminderTitle" placeholder="What should I remind you about?"></div><div class="quick-fields-row"><div class="form-field"><label>DATE</label><input id="newReminderDate" type="date" value="${localISO()}"></div><div class="form-field"><label>TIME</label><input id="newReminderTime" type="time" value="${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}"></div><div class="form-field"><label>TYPE</label><select id="newReminderType"><option>Personal</option><option>BMC</option></select></div></div>`,()=>{let title=$('#newReminderTitle').value.trim(),date=$('#newReminderDate').value,raw=$('#newReminderTime').value;if(!title)return toast('Write the reminder first.');tasks.unshift({id:'task-'+Date.now().toString(36),title,date,day:dateLabel(date),time:new Date('2026-01-01T'+raw).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'}),type:$('#newReminderType').value,category:'Reminder',sub:'Reminder',done:false});store.set('tide_tasks',tasks);renderTasks();$('#modal').classList.remove('open');toast('Reminder added to the To Do List.')})}
function openAddFollowup(){let now=new Date();modal('Add client follow-up','It will appear here and in your To Do List.',`<div class="form-field"><label>CLIENT / FOLLOW-UP</label><input id="newFollowupTitle" placeholder="e.g. Call Rohan about proposal"></div><div class="quick-fields-row"><div class="form-field"><label>DATE</label><input id="newFollowupDate" type="date" value="${localISO()}"></div><div class="form-field"><label>TIME</label><input id="newFollowupTime" type="time" value="${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}"></div><div class="form-field"><label>TYPE</label><select><option>Client</option></select></div></div>`,()=>{let title=$('#newFollowupTitle').value.trim(),date=$('#newFollowupDate').value,raw=$('#newFollowupTime').value;if(!title)return toast('Write the follow-up first.');tasks.unshift({id:'task-'+Date.now().toString(36),title,date,day:dateLabel(date),time:new Date('2026-01-01T'+raw).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'}),type:'Work',category:'Follow-up',sub:'Client follow-up',done:false});store.set('tide_tasks',tasks);renderTasks();$('#modal').classList.remove('open');toast('Follow-up added to the To Do List.')})}
let monthFeedOffset=0;
function monthFeedItems(){let combined=[...tasks.map(t=>{let cat=taskCategory(t),kind=cat==='Follow-up'?'followup':cat.toLowerCase();return{title:t.title,time:t.time||currentTimeText(),date:taskDateISO(t),taskId:t.id,kind,category:cat,meta:[t.client,t.service,cat,t.done?'Completed':'Pending'].filter(Boolean).join(' · '),done:t.done}}),...meetings.map(m=>({title:m.title,time:m.time||currentTimeText(),date:meetingDateISO(m),kind:'meeting',category:'Meeting',meta:m.client||m.sub||'Meeting',done:false}))];let seen=new Set();return combined.filter(x=>{let key=x.date+'|'+x.title.toLowerCase();if(seen.has(key))return false;seen.add(key);return true})}
function renderMonthFeed(offset=monthFeedOffset){monthFeedOffset=offset;let base=new Date(),view=new Date(base.getFullYear(),base.getMonth()+offset,1),year=view.getFullYear(),month=view.getMonth(),items=monthFeedItems().filter(x=>{let d=new Date(x.date+'T00:00:00');return d.getFullYear()===year&&d.getMonth()===month}).sort((a,b)=>{let today=localISO();if(a.date===b.date)return a.time.localeCompare(b.time);if(a.date===today)return-1;if(b.date===today)return 1;let ap=a.date<today,bp=b.date<today;if(ap&&bp)return b.date.localeCompare(a.date);if(ap!==bp)return ap?-1:1;return a.date.localeCompare(b.date)}),groups={};items.forEach(x=>(groups[x.date]??=[]).push(x));$('#monthFeedTitle').textContent=view.toLocaleDateString('en-IN',{month:'long',year:'numeric'});$('#monthTaskFeed').innerHTML=Object.keys(groups).length?Object.entries(groups).map(([date,list])=>{let d=new Date(date+'T00:00:00');return`<div class="month-day"><div class="month-day-head"><strong>${d.toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</strong><span>${d.toLocaleDateString('en-IN',{weekday:'long'})}</span></div>${list.map(x=>`<div class="month-feed-item" data-feed-date="${date}"><span class="month-category-strip ${x.kind}">${escapeHtml(x.category||'Task')}</span><div><strong style="${x.done?'text-decoration:line-through;opacity:.55':''}">${escapeHtml(x.title)}</strong><p>${escapeHtml(x.meta)}</p></div><span>${x.time}</span>${x.taskId?`<button class="month-check ${x.done?'checked':''}" data-month-check="${x.taskId}" aria-label="Complete task">${x.done?'✓':''}</button>`:'<span></span>'}</div>`).join('')}</div>`}).join(''):'<div class="empty-agenda"><span>□</span><strong>No tasks in this month</strong><p>Add a task and it will automatically appear here.</p></div>';$$('[data-feed-date]').forEach(x=>x.onclick=()=>openTaskQueue(x.dataset.feedDate));$$('[data-month-check]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleTaskEverywhere(b.dataset.monthCheck)})}
function toggleTaskEverywhere(id){let task=tasks.find(t=>t.id===id);if(!task)return;task.done=!task.done;if(task.done)task.completedAt=currentTimeText();else delete task.completedAt;store.set('tide_tasks',tasks);renderTasks();renderCalendar(weekOffset);toast(task.done?'Completed everywhere.':'Moved back to pending everywhere.')}
let selectedCalIndex=2;
function itemDay(x){if(x.day)return x.day;if((x.sub||'').includes('Tomorrow'))return'Tomorrow';return'Today'}
function allCalendarItems(){return[...meetings.map((x,i)=>({...x,source:'Meeting',sourceIndex:i})),...tasks.filter(x=>!x.done).map((x,i)=>({...x,source:'Task',sourceIndex:tasks.indexOf(x)}))]}
function detailMeta(x){return [x.client&&`Client: ${x.client}`,x.service&&`Service: ${x.service}`,x.assignee&&x.assignee!=='Myself'&&`Assigned: ${x.assignee}`,x.notes].filter(Boolean)}
function renderCalendar(offset=0){
 let days=['MON','TUE','WED','THU','FRI','SAT','SUN'],nums=[17,18,19,20,21,22,23].map(n=>n+offset*7);
 $('#weekDays').innerHTML=days.map((d,i)=>`<div class="day ${i===selectedCalIndex?'active':''}" data-cal-day="${i}" role="button" tabindex="0"><small>${d}</small><strong>${nums[i]}</strong></div>`).join('');
 $('#calRange').textContent=`${nums[0]}–${nums[6]} August 2026`;
 $$('[data-cal-day]').forEach(d=>{d.onclick=()=>{selectedCalIndex=+d.dataset.calDay;renderCalendar(offset)};d.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();d.click()}}});
 let labels=['Monday','Tuesday','Today','Tomorrow','Friday','Saturday','Sunday'],label=offset===0?labels[selectedCalIndex]:days[selectedCalIndex];
 let all=allCalendarItems(),list=all.filter(x=>{let md=itemDay(x);if(offset!==0)return false;if(label==='Today')return md==='Today';if(label==='Tomorrow')return md==='Tomorrow'||md==='Thursday';return md.toLowerCase()===label.toLowerCase()});
 $('#agenda').innerHTML=`<div class="agenda-label"><strong>${label} — Detailed tasks</strong><span>${list.length} ${list.length===1?'item':'items'}</span></div>`+(list.length?list.map(x=>`<div class="agenda-row"><time>${x.time||currentTimeText()}</time><div class="event ${x.kind||''}" data-calendar-source="${x.source}" data-calendar-index="${x.sourceIndex}"><h4>${escapeHtml(x.title)}</h4><p>${x.source} · ${x.type||x.sub||''}</p><div class="event-details">${detailMeta(x).map(m=>`<span>${escapeHtml(m)}</span>`).join('')||`<span>${escapeHtml(x.sub||'No extra details')}</span>`}</div></div></div>`).join(''):`<div class="empty-agenda"><span>□</span><strong>Nothing planned for ${label.toLowerCase()}</strong><p>Your time is open. Add a detailed item from Brain Dump.</p></div>`);
 $$('[data-calendar-source]').forEach(e=>e.onclick=()=>e.dataset.calendarSource==='Task'?openTaskActions(+e.dataset.calendarIndex):finishMeeting());
 $('#upcomingList').innerHTML=all.slice(0,5).map(x=>`<div class="upcoming-item"><strong>${escapeHtml(x.title)}</strong><span>${itemDay(x)} · ${x.time||currentTimeText()} · ${x.source}</span></div>`).join('')
}
function renderCalendarOverview(view){
 let all=allCalendarItems(),weekly=view==='weekly',groups=weekly?['Today','Tomorrow','Friday','Saturday','Sunday']:['Week 1','Week 2','Week 3','Week 4'];
 let distribute=g=>weekly?all.filter(x=>itemDay(x)===g||(g==='Tomorrow'&&itemDay(x)==='Thursday')):all.filter((x,i)=>i%4===groups.indexOf(g));
 $('#calendarOverview').innerHTML=`<div class="overview-head"><div><p class="eyebrow">${weekly?'WEEKLY':'MONTHLY'} UPDATE</p><h2>${weekly?'Your detailed week.':'Your detailed month.'}</h2><p>Tasks, meetings, clients and delivered services in one view.</p></div><span>${all.length} scheduled items</span></div><div class="overview-groups">${groups.map(g=>{let list=distribute(g);return`<div class="overview-group"><div class="overview-group-head"><strong>${g}</strong><span>${list.length} items</span></div>${list.length?list.map(x=>`<div class="detail-task"><time>${x.time||currentTimeText()}</time><div><h4>${escapeHtml(x.title)}</h4><p>${[x.client,x.service,x.assignee,x.notes].filter(Boolean).map(escapeHtml).join(' · ')||escapeHtml(x.sub||x.type||x.source)}</p></div><span>${x.source}</span></div>`).join(''):'<div class="detail-task"><time>—</time><div><h4>No items</h4><p>Your schedule is clear.</p></div><span>Open</span></div>'}</div>`}).join('')}</div>`
}
let weekOffset=0;$('#prevWeek').onclick=()=>{selectedCalIndex=0;renderCalendar(--weekOffset)};$('#nextWeek').onclick=()=>{selectedCalIndex=0;renderCalendar(++weekOffset)};$('#todayBtn').onclick=()=>{weekOffset=0;selectedCalIndex=2;renderCalendar()};
$$('[data-calendar-view]').forEach(b=>b.onclick=()=>{$$('[data-calendar-view]').forEach(x=>x.classList.toggle('active',x===b));let daily=b.dataset.calendarView==='daily';$('#dailyCalendarView').classList.toggle('hidden',!daily);$('#calendarOverview').classList.toggle('active',!daily);if(!daily)renderCalendarOverview(b.dataset.calendarView)});
