function setupHeroSwipe(){let card=$('#nextCard'),green=$('#heroGreen'),startX=0,active=false,moved=false;card.onpointerdown=e=>{if(e.target.closest('button'))return;active=true;moved=false;startX=e.clientX;card.setPointerCapture?.(e.pointerId);green.style.transition='none'};card.onpointermove=e=>{if(!active)return;let dx=Math.max(0,e.clientX-startX);if(dx>7)moved=true;if(moved){card.classList.add('swiping');green.style.width=Math.min(100,dx/card.clientWidth*100)+'%'}};card.onpointerup=card.onpointercancel=e=>{if(!active)return;active=false;let dx=Math.max(0,e.clientX-startX),done=dx>card.clientWidth*.38;green.style.transition='width .16s ease';card.classList.remove('swiping');if(done&&currentTaskIndex()>=0){card.classList.add('completed-swipe');green.style.width='100%';setTimeout(()=>{completeCurrentTask();card.classList.remove('completed-swipe');green.style.width='0'},260)}else{green.style.width='0';if(!moved)openTaskQueue(localISO())}}}
